# Define a CloudWatch Event Rule to capture AWS GuardDuty findings
resource "aws_cloudwatch_event_rule" "guardduty_events" {
  name        = "cg-guardduty-events-${var.cgid}"
  event_pattern = jsonencode({
    "source" : ["aws.guardduty"],
    "detail-type" : ["GuardDuty Finding"],
    "detail": {
      "type": [
        "UnauthorizedAccess:IAMUser/InstanceCredentialExfiltration.OutsideAWS",
      ]
    }
  })
}

# Create a target for the CloudWatch Event Rule to invoke a Lambda function
resource "aws_cloudwatch_event_target" "ecs_event_target" {
  rule = aws_cloudwatch_event_rule.guardduty_events.name
  arn  = aws_lambda_function.guardduty_lambda.arn
}

# Enable AWS GuardDuty for threat detection and continuous monitoring
# Note : The GuardDuty in the user account must be completely disabled to function normally.
resource "aws_guardduty_detector" "detector" {
  enable = true
}

resource "aws_cloudwatch_log_group" "lambda_log" {
  name = "/aws/lambda/${aws_lambda_function.guardduty_lambda.function_name}"
}

data "aws_caller_identity" "current" {}

# Search based on tag to get the IP of EC2 that is automatically generated by ASG.
data "aws_instances" "asg_instance" {
  depends_on = [time_sleep.wait_for_instance]

  instance_tags = {
    Name = "cg-ec2-instance-${var.cgid}"
  }
}

data "aws_availability_zones" "current_az" {
  state = "available"
}

# Get AMI of the latest version of Amazon Linux 2 for ECS.
data "aws_ami" "latest_amazon_linux" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-*-x86_64-ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  owners = ["amazon"]
}

# compress index.py to lambda.zip
data "archive_file" "lambda_zip" {
  type             = "zip"
  source_file      = "./index.py"
  output_file_mode = "0666"
  output_path      = "./lambda.zip"
}

resource "aws_ecr_repository" "repository" {
  name = "cg-repository-${var.cgid}"
}

resource "null_resource" "docker_image" {

  # Push Docker image when the scenario be created
  provisioner "local-exec" {
    when       = create
    on_failure = fail
    command    = "python3 ./push-dockerfile.py --dockerfile_path ../assets/ssrf-web/ --repository ${aws_ecr_repository.repository.name} --region ${var.region} --profile ${var.profile} --image_tag latest"
  }

  # Pop Docker images when the scenario be destroyed
  provisioner "local-exec" {
    when       = destroy
    on_failure = fail
    command    = "python3 ./pop-dockerfile.py --repository ${self.triggers.repository_name} --region ${self.triggers.region} --profile ${self.triggers.profile} --image_tag all"
  }

  triggers = {
    repository_name = aws_ecr_repository.repository.name
    region          = var.region
    profile         = var.profile
  }

  depends_on = [aws_ecr_repository.repository]
}

# Creating an ECS Cluster.
resource "aws_ecs_cluster" "cluster" {
  name = "cg-cluster-${var.cgid}"
}

# Setting up capacity providers for the ECS Cluster
# In consideration of the performance issues caused by EC2 created as t2.micro, we also added FARGATE for smooth scenario solving.
resource "aws_ecs_cluster_capacity_providers" "providers" {
  cluster_name = aws_ecs_cluster.cluster.name

  capacity_providers = [
    "FARGATE",
    "FARGATE_SPOT",
    aws_ecs_capacity_provider.capacity_provider.name
  ]
}

# Defining an ECS capacity provider using an Auto Scaling group.
# ASG would have only one instance.
resource "aws_ecs_capacity_provider" "capacity_provider" {
  name = "cg-provider-${var.cgid}"

  auto_scaling_group_provider {
    auto_scaling_group_arn         = aws_autoscaling_group.asg.arn
    managed_termination_protection = "DISABLED"

    managed_scaling {
      status                    = "ENABLED"
      maximum_scaling_step_size = 1
      minimum_scaling_step_size = 1
      target_capacity           = 50
    }
  }
}

# Defining an ECS capacity provider using an Auto Scaling group.
# ASG would have only one instance.
resource "aws_autoscaling_group" "asg" {
  name = "cg-asg-${var.cgid}"

  desired_capacity    = 1
  max_size            = 1
  min_size            = 1
  vpc_zone_identifier = [aws_subnet.public.id]

  tag {
    key                 = "Name"
    value               = "cg-ec2-instance-${var.cgid}"
    propagate_at_launch = true
  }

  launch_template {
    id      = aws_launch_template.template.id
    version = "$Latest"
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Define EC2 launch template for ASG.
# ami            : Amazon Linux 2 for ECS
# instance type  : t2.micro
# security_group : allow http (whitelists apply), and all outbound.
# allow IMDSv1
resource "aws_launch_template" "template" {
  name          = "cg-launch-template-${var.cgid}"
  image_id      = data.aws_ami.latest_amazon_linux.id
  instance_type = "t2.micro"

  iam_instance_profile {
    name = aws_iam_instance_profile.profile.name
  }

  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [aws_security_group.allow_http.id]
  }

  metadata_options {
    http_tokens = "optional"
  }

  user_data = base64encode(
    <<EOF
#!/bin/bash
echo ECS_CLUSTER=${aws_ecs_cluster.cluster.name} >> /etc/ecs/ecs.config;
EOF
  )
}

# IAM Role for EC2 instance
resource "aws_iam_instance_profile" "profile" {
  name = "cg-ec2-role-${var.cgid}"
  role = aws_iam_role.ec2_role.name
}

# Define ECS Service as vulnerable web.
# Web will be launch on container in EC2.
resource "aws_ecs_service" "ssrf_web_service" {
  name            = "cg-service-${var.cgid}"
  cluster         = aws_ecs_cluster.cluster.id
  task_definition = aws_ecs_task_definition.web_task.arn
  launch_type     = "EC2"
  desired_count   = 1
}

# Define details for Web task.
# Bridge network for access EC2 metadata.
# Containers would be imported from ECR
resource "aws_ecs_task_definition" "web_task" {
  family                   = "cg-task-service-ssrf-web"
  network_mode             = "bridge"
  requires_compatibilities = ["EC2"]
  cpu                      = "512"
  memory                   = "512"
  depends_on               = [null_resource.docker_image]

  container_definitions = jsonencode([{
    name  = "cg-ssrf-web-${var.cgid}",
    image = "${aws_ecr_repository.repository.repository_url}:latest"

    portMappings = [{
      containerPort = 80,
      hostPort      = 80,
    }],

    healthCheck = {
      command     = ["CMD-SHELL", "curl -f http://localhost/ || exit 1"],
      interval    = 10,
      timeout     = 5,
      retries     = 3,
      startPeriod = 15
    }
  }])
}

# Wait a little for ec2 be created in ASG.
resource "time_sleep" "wait_for_instance" {
  depends_on = [aws_autoscaling_group.asg]
  create_duration = "30s"
}

# Define IAM role for EC2 Instance.
# Assume that excessive privileges are set for this role.
# ec2_role & ec2_role_sub are twin role for renewing credentials.
# Once lambda run, ec2's role would be change to another, and credential's will be renewed.
resource "aws_iam_role" "ec2_role" {
  name = "cg-web-developer-${var.cgid}"
  tags = {
    deployment_profile = var.profile
    Stack              = var.stack-name
    Scenario           = var.scenario-name
  }

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role",
    aws_iam_policy.cg_web_developer_policy.arn
  ]

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "ec2.amazonaws.com",
            "ecs-tasks.amazonaws.com"
          ]
        }
      },
    ]
  })
}

# Define IAM role for EC2 Instance.
# Assume that excessive privileges are set for this role.
resource "aws_iam_role" "ec2_role_sub" {
  name = "cg-web-developer-sub-${var.cgid}"
  tags = {
    deployment_profile = var.profile
    Stack              = var.stack-name
    Scenario           = var.scenario-name
  }

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role",
    aws_iam_policy.cg_web_developer_policy.arn
  ]

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "ec2.amazonaws.com",
            "ecs-tasks.amazonaws.com"
          ]
        }
      },
    ]
  })
}

# Target of Privesc.
# Using PassRole, ECS
resource "aws_iam_role" "s3_access" {
  name = "cg-s3-critical-${var.cgid}"
  tags = {
    deployment_profile = var.profile
    Stack              = var.stack-name
    Scenario           = var.scenario-name
  }

  managed_policy_arns = ["arn:aws:iam::aws:policy/AmazonS3FullAccess"]

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com"
          ]
        }
      },
    ]
  })
}

# Define Lambda's role for sending mail if GuardDuty detects an attack.
# The mail will be sent with SES.
resource "aws_iam_role" "lambda_role" {
  name = "cg-lambda-role-${var.cgid}"
  tags = {
    deployment_profile = var.profile
    Stack              = var.stack-name
    Scenario           = var.scenario-name
  }

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonSESFullAccess",
    "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  ]

  inline_policy {
    name = "cg-lambda-inline-policy"
    policy = jsonencode({
      Version = "2012-10-17",
      Statement = [
        {
          Effect   = "Allow",
          Action   = [
            "iam:DetachRolePolicy",
            "iam:AttachRolePolicy",
            "iam:ListAttachedRolePolicies",
            "iam:GetRole",
            "iam:PassRole",
            "iam:ListAttachedRolePolicies",
            "iam:ListRolePolicies",
            "iam:GetRolePolicy",
            "iam:PutRolePolicy",
            "iam:DeleteRolePolicy"
          ],
          Resource = [
            aws_iam_role.ec2_role.arn,
            aws_iam_role.ec2_role_sub.arn
          ]
        },{
          Effect   = "Allow",
          Action   = [
            "guardduty:ListFindings",
            "guardduty:UpdateFindingsFeedback",
            "ec2:DescribeIamInstanceProfileAssociations",
            "ec2:ReplaceIamInstanceProfileAssociation"
          ],
          Resource = "*"
        }
      ]
    })
  }

  assume_role_policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Action" : "sts:AssumeRole",
        "Effect" : "Allow",
        "Principal" : {
          "Service" : "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Even if users play Easy Path, users also can know that secret-string.txt exists but cannot to see what is in.
resource "aws_iam_policy" "cg_web_developer_policy" {
  name   = "cg-web-developer-policy-${var.cgid}"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect    = "Allow",
        Resource  = "*",
        Action    = [
          "ec2:DescribeInstances",
          "ec2:DescribeSubnets",
          "s3:ListAllMyBuckets",
          "ecs:RegisterTaskDefinition",
          "ecs:ListClusters",
          "iam:List*"
        ]
      },{
        Effect    = "Allow",
        Resource  = [
          "arn:aws:ecs:${var.region}:${data.aws_caller_identity.current.account_id}:capacity-provider/cg-provider-${var.cgid}",
          "arn:aws:ecs:${var.region}:${data.aws_caller_identity.current.account_id}:cluster/cg-cluster-${var.cgid}",
          "arn:aws:ecs:${var.region}:${data.aws_caller_identity.current.account_id}:task/cg-cluster-${var.cgid}/*",
          "arn:aws:ecs:${var.region}:${data.aws_caller_identity.current.account_id}:task-definition/*"
        ],
        Action    = [
          "ecs:RunTask",
          "ecs:Describe*",
          "ecs:List*",
        ]
      },{
        Effect    = "Allow",
        Resource  = [
          aws_s3_bucket.secret-s3-bucket.arn,
          "${aws_s3_bucket.secret-s3-bucket.arn}/*"
        ],
        Action    = [
          "s3:List*",
          "s3:GetBucketLocation"
        ]
      },{
        Effect    = "Allow",
        Resource  = "${aws_s3_bucket.secret-s3-bucket.arn}/flag.txt",
        Action    = "s3:GetObject"
      },{
        Effect    = "Allow",
        Resource  = [
          aws_iam_role.s3_access.arn,
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/cg-web-developer-sub-${var.cgid}",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/cg-web-developer-${var.cgid}",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/cg-web-developer-policy-${var.cgid}"
        ],
        Action    = [
          "iam:Get*",
          "iam:PassRole"
        ]
      }
    ]
  })
}

# Getting instance profile for lambda
resource "aws_iam_instance_profile" "instance_profile_1" {
  name = "cg-instance-profile-${var.cgid}"
  role = aws_iam_role.ec2_role.name
}

resource "aws_iam_instance_profile" "instance_profile_2" {
  name = "cg-instance-profile-sub-${var.cgid}"
  role = aws_iam_role.ec2_role_sub.name
}

#Required: Always output the AWS Account ID
output "cloudgoat_output_aws_account_id" {
  value = data.aws_caller_identity.current.account_id
}

# Scenario starts at ssrf web url.
output "ssrf_web_url" {
  # During scenario destroy, there is no string left in the list, resulting in an error.
  # So make value = "", when list's length 0.
  value = length(data.aws_instances.asg_instance.public_ips) > 0 ? "Scenario start at : http://${data.aws_instances.asg_instance.public_ips[0]}" : ""
}

terraform {
  required_version = ">= 1.6"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4"
    }
    time = {
      source  = "hashicorp/time"
      version = ">= 0.9"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region
}

#Secret S3 Bucket
locals {
  # Ensure the bucket suffix doesn't contain invalid characters
  # "Bucket names can consist only of lowercase letters, numbers, dots (.), and hyphens (-)."
  # (per https://docs.aws.amazon.com/AmazonS3/latest/userguide/bucketnamingrules.html)
  bucket_suffix = replace(var.cgid, "/[^a-z0-9-.]/", "-")
}

# Create Secret Bucket
resource "aws_s3_bucket" "secret-s3-bucket" {
  bucket        = "cg-s3-${local.bucket_suffix}"
  force_destroy = true
}

# Store secret string for easy path in flag.txt
resource "aws_s3_object" "credentials_easy_path" {
  bucket = aws_s3_bucket.secret-s3-bucket.id
  key    = "flag.txt"
  source = "./flag.txt"
}

# Store secret string for hard path in critical.txt
resource "aws_s3_object" "credentials_hard_path" {
  bucket = aws_s3_bucket.secret-s3-bucket.id
  key    = "secret-string.txt"
  source = "./secret-string.txt"
}

# AWS CLI logs for GuardDuty analysis
resource "aws_s3_bucket" "cloudtrail_bucket" {
  bucket        = "cg-cloudtrail-s3-${local.bucket_suffix}"
  force_destroy = true
}

# Block public access for Cloudtrail Logs Bucket
resource "aws_s3_bucket_public_access_block" "trail_bucket_block_public" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  restrict_public_buckets = true
  ignore_public_acls      = true
}

resource "aws_s3_bucket_policy" "trail_bucket_policy" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = "s3:GetObject",
        Resource = "${aws_s3_bucket.cloudtrail_bucket.arn}/*",
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
      },{
        Effect = "Allow",
        Action = "s3:PutObject",
        Resource = "${aws_s3_bucket.cloudtrail_bucket.arn}/*",
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        },
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },{
        Effect = "Allow",
        Action = "s3:GetBucketAcl",
        Resource = aws_s3_bucket.cloudtrail_bucket.arn,
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
      }
    ]
  })
}

# Create SES for sending emails.
resource "aws_ses_email_identity" "email" {
  email = var.user_email
}

variable "profile" {
  description = "The AWS profile to use."
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources to."
  default     = "us-east-1"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming."
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)."
  type        = list(string)
  default     = ["127.0.0.1/24"]
}

variable "stack-name" {
  description = "Name of the stack."
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario."
  default     = "ecs_privesc_evade_protection"
  type        = string
}

variable "user_email" {
  description = "Once guardduty detects attack, a mail will be sent to you"
  type        = string
}

resource "aws_vpc" "vpc" {
  cidr_block           = "192.168.150.0/24"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    "Name" = "cg-${var.cgid}-main"
  }
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    "Name" = "cg-${var.cgid}-main"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.vpc.id
  availability_zone = data.aws_availability_zones.current_az.names[0]
  cidr_block        = "192.168.150.0/26"

  tags = {
    "Name" = "cg-${var.cgid}-public"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.internet_gateway.id
  }

  tags = {
    "Name" = "cg-${var.cgid}-public"
  }
}

resource "aws_route_table_association" "route_table_association" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Security Group for EC2
# Allow http from whitelist IP.
# Allow All outbound.
resource "aws_security_group" "allow_http" {
  name        = "cg-${var.cgid}-allow-http"
  description = "Allow inbound traffic on port 80 from whitelist IP"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cg-allow-http-${var.cgid}"
  }
}
